#!/usr/bin/env python3
"""Single source for both C4 Markdown formats; generated by render.py."""
import sys
from html import escape
from textwrap import wrap
from canvas import Canvas

TITLE = 'Container — observability path'
BOUNDARY = 'Platform observability'
NODES = [('server',
  'Server process',
  'Deno process',
  'platform/server.ts',
  'LoggingLive; HTTP, handler, SQL, tx and lifecycle',
  True),
 ('reader',
  'Reader process',
  'Deno child process',
  'platform/reader.ts; reader_layers.ts',
  'Reader logging; ingest-then-sweep; live analysis',
  True),
 ('jsonl',
  'Structured event sources',
  'Filesystem',
  'LOG_DIR/role/date/events-*.jsonl',
  'Server/reader JSONL; quarantine beside source',
  True),
 ('duck',
  'Derived event log',
  'DuckDB file',
  'EVENTLOG_DUCKDB',
  'Schema v2; typed events, watermarks and k6_points',
  True),
 ('cli',
  'Logs CLI',
  'Deno process',
  'scripts/logs.ts',
  'Ingest/list/query/sweep; named catalog',
  True),
 ('loader',
  'k6 point loader',
  'Deno process',
  'perf/ingest_k6.ts',
  'Loads raw points into k6_points (item 25)',
  True),
 ('k6db', 'k6 metrics file', 'DuckDB file', 'logs/k6/run-id/k6.duckdb',
  'Default loader target; K6_DUCKDB overrides', True),
 ('results', 'k6 artifacts', 'Filesystem', 'logs/k6/run-id/', 'raw.json and summary.json', True),
 ('k6',
  'k6 load generator',
  'External process',
  'perf/*.js',
  'HTTP load; JSON metric output',
  False)]
EDGES = [('server', 'jsonl', 'Append structured JSONL through dropping queue'),
 ('reader', 'jsonl', 'Append reader-role JSONL; stdout reserved for RPC'),
 ('server', 'reader', 'JSONL ingest/analysis RPC; timer and admin HTTP'),
 ('reader', 'duck', 'Transactional ingest; shared-instance catalog SELECT'),
 ('reader', 'jsonl', 'After committed ingest: seal tails, gzip/delete safe files'),
 ('cli', 'duck', 'Offline ingest or read-only catalog SELECT'),
 ('cli', 'jsonl', 'Offline ingest-then-sweep; dry-run plans only'),
 ('k6', 'results', 'Raw points and summary JSON'),
 ('results', 'loader', 'Read raw.json for selected run id'),
 ('loader', 'k6db', 'Default: replace selected run k6_points'),
 ('loader', 'duck', 'Offline only: K6_DUCKDB override co-locates catalog data')]
NOTES = 'Item 23 provides the named catalog and logs CLI; item 25 provides the k6 loader and join acceptance\ntest. MT-10 wires the reader analysis RPC and shares the ingest instance so later commits remain visible.\nThe server never opens DuckDB. The standalone CLI queries read-only and can fail while a writer owns the\nfile; use the live admin route during serving. Ingest and analysis handles are independently scoped\nconnections on the shared native instance. Per-app query readers are independent of the event log.\nRetention bounds JSONL only, requires committed watermarks and matching hashes, and never touches today\nor the reader sink open path. Derived tables are never pruned; logs:compact remains future work.\nGzipped retained sources are not re-ingested by the current scanner. No load-performance result is\nclaimed by this diagram.'
NOTES += '\nReader restart lifecycle events are emitted by platform/layers.ts into the server sink. A child crash\nmay lose buffered reader events; restart is availability recovery, not durable audit delivery.\nSchema v2 has no tenant identity in the envelope or typed tables. Analysis is admin-global, not tenant\nscoped; app_id and caller-controlled trace_id cannot safely reconstruct tenant attribution.'
NOTES += '\nThe k6 loader defaults to a separate k6.duckdb, not EVENTLOG_DUCKDB. The observability acceptance\nprogram attaches the stopped server event log. The named catalog expects k6_points in its own file;\nuse K6_DUCKDB to ingest into the stopped event log, or an explicit offline attach query. The catalog\ncurrently compares all HTTP events in overlapping time buckets; it does not isolate the run workload.'
NAME = 'c4-container-observability'


def picture():
    cv = Canvas(width=72, height=260)
    row = 2
    for inside in (True, False):
        group = [n for n in NODES if n[5] == inside]
        if not inside:
            cv.frame(0, 0, row, 71, BOUNDARY)
            row += 2
        for offset in range(0, len(group), 2):
            bottoms = []
            for col, (_, title, kind, path, detail, _) in enumerate(group[offset:offset+2]):
                lines = [part for line in [title, '[' + kind + ']', path, detail]
                         for part in wrap(line, 28, break_on_hyphens=False)]
                bottoms.append(cv.box(row, 3 + col*35, 32, lines))
            row = max(bottoms) + 2
    return cv.render()


def mermaid():
    lines = ['flowchart TB', '    subgraph platform["' + BOUNDARY + '"]']
    for inside in (True, False):
        for id, title, kind, path, detail, within in NODES:
            if within == inside:
                label = '<br/>'.join(escape(s, quote=True) for s in [title, '['+kind+']', path, detail])
                lines.append('        ' + id + '["' + label + '"]')
        if inside:
            lines.append('    end')
    for i, (a, b, label) in enumerate(EDGES, 1):
        lines.append(f'    {a} -->|"({i}) {label}"| {b}')
    lines += ['    classDef planned stroke-dasharray: 5 3',
              '    classDef person fill:#fff,stroke-width:2px',
              '    classDef external fill:#f4f4f4']
    for id, _, kind, _, _, inside in NODES:
        if kind == 'Person':
            lines.append(f'    class {id} person')
        elif not inside:
            lines.append(f'    class {id} external')
    return '\n'.join(lines)


def document(github):
    text = '# ' + TITLE + '\n\nAudited against landed main `cd669d1` on 2026-10-11 (reflection astra-2). Both formats are generated from\n'
    text += '`diagrams/' + NAME + '.py`; numbered relationships are identical. All boxes describe landed code.\n\n'
    if github:
        text += '```mermaid\n' + mermaid() + '\n```\n'
    else:
        text += '<!-- c4-render: diagrams/' + NAME + '.py -->\n\n```text\n' + picture() + '\n```\n'
    names = {n[0]: n[1] for n in NODES}
    text += '\n## Relationships\n\n| # | From | To | Relationship |\n| - | --- | --- | --- |\n'
    for i, (a,b,label) in enumerate(EDGES,1):
        text += f'| {i} | {names[a]} | {names[b]} | {label} |\n'
    return text + '\n## Runtime notes\n\n' + NOTES + '\n'


if __name__ == '__main__':
    if '--github' in sys.argv:
        print(document(True), end='')
    elif '--terminal' in sys.argv:
        print(document(False), end='')
    else:
        print(picture())
